const SAMPLE: &str = r#"<html>
<h1><?php echo "hi"; ?></h1>
<?php
namespace App\Models;
use App\Contracts\HasName;
use App\Support\{Str, Arr as A};
interface Shape extends Drawable, Sized {}
trait Loggable { public function log(string $m): void {} }
enum Status: string implements HasName { case On = 'on'; }
abstract class Animal extends Base implements Speaker, \Countable {
    public function speak(): string { return $this->sound(); }
    abstract protected function sound();
    public static function make() { return new static(); }
}
function helper(int $count, $z = 0) {
    $z = 5;
    $z += 1;
    $z++;
    $total = strlen($z) + Foo\bar($count);
    $obj?->nullsafe();
    Animal::make();
    return $total;
}
?>
<p>end</p>
"#;

fn run(lang: &tree_sitter::Language, q: &str, label: &str, src: &str, tree: &tree_sitter::Tree) {
    let query = match Query::new(lang, q) {
        Ok(q) => q,
        Err(e) => { println!("[{label}] QUERY ERROR: {e}"); return; }
    };
    let mut cursor = QueryCursor::new();
    let mut matches = cursor.matches(&query, tree.root_node(), src.as_bytes());
    let mut out = Vec::new();
    while let Some(m) = matches.next() {
        for c in m.captures {
            let name = query.capture_names()[c.index as usize];
            let text = c.node.utf8_text(src.as_bytes()).unwrap_or("?");
            out.push(format!("{name}={text}@{}:{}", c.node.kind(), c.node.start_position().row + 1));
        }
    }
    println!("[{label}] {} captures: {}", out.len(), out.join(" | "));
}

fn main() {
    let lang: tree_sitter::Language = tree_sitter_php::LANGUAGE_PHP.into();
    let mut parser = Parser::new();
    parser.set_language(&lang).expect("lang");
    let tree = parser.parse(SAMPLE, None).expect("parse");
    println!("root has_error={}", tree.root_node().has_error());
    fn walk(n: tree_sitter::Node, depth: usize, out: &mut Vec<String>) {
        if n.is_error() || n.is_missing() { out.push(format!("{}{} err/missing", " ".repeat(depth), n.kind())); }
        let mut c = n.walk();
        for ch in n.children(&mut c) { walk(ch, depth + 1, out); }
    }
    let mut errs = Vec::new();
    walk(tree.root_node(), 0, &mut errs);
    println!("error_nodes={} {:?}", errs.len(), errs.iter().take(5).collect::<Vec<_>>());
    run(&lang, ELEMENT_QUERY, "element", SAMPLE, &tree);
    run(&lang, CALL_QUERY, "call", SAMPLE, &tree);
    run(&lang, REFERENCE_QUERY, "reference", SAMPLE, &tree);
    run(&lang, IMPORT_QUERY, "import", SAMPLE, &tree);
    run(&lang, DEFUSE_QUERY, "defuse", SAMPLE, &tree);
    // inheritance walk
    let root = tree.root_node();
    let mut stack = vec![root];
    while let Some(n) = stack.pop() {
        if matches!(n.kind(), "class_declaration" | "interface_declaration") {
            let mut c = n.walk();
            let kids: Vec<String> = n.children(&mut c).filter(|k| k.is_named()).map(|k| format!("{}", k.kind())).collect();
            println!("{} named children: {:?}", n.kind(), kids);
            let mut c2 = n.walk();
            for k in n.children(&mut c2) {
                if k.kind() == "base_clause" || k.kind() == "class_interface_clause" {
                    let mut c3 = k.walk();
                    let names: Vec<String> = k.named_children(&mut c3).map(|x| format!("{}:{}", x.kind(), &SAMPLE[x.byte_range()])).collect();
                    println!("  {} -> {:?}", k.kind(), names);
                }
            }
        }
        let mut c = n.walk();
        for ch in n.children(&mut c) { stack.push(ch); }
    }
}
EOF
(cargo build --offline --release > build.log 2>&1; echo "BUILD_EXIT=$?" >> build.log) &
sleep 2; tail -3 build.log

